NEW_FILES = {'documentation/smoke_label_words.js': '// smoke_label_words.js -- naming a drawer row opens that row\'s own\n// feature\'s words, in the Sun and Earth rooms (L-468).\n//\n// RUN:  node documentation/smoke_label_words.js   (gallery root)\n//\n// WHY THIS EXISTS\n//   On 2026-10-21 Tony named the corona\'s row in the Sun room\'s drawer\n//   and its text box opened the streamer belt\'s words. Since the belt\n//   joined the corona\'s row (L-410, 2026-10-19), the row holds two info\n//   crosses, and the page opened the first, which was the belt\'s. Nothing\n//   checked which words a row opens.\n//\n// WHAT IT CHECKS\n//   Both rooms are built with the real renderers from the served config\n//   and the served cache\'s stored drawings, as smoke_drawn_ends.js builds\n//   them. The traces are grouped by legend group, as the drawer groups\n//   them. For every row that is a served shell (its traces carry a shell\n//   key), the trace GalleryFeatures.labelTraceIndex picks -- the page\'s\n//   own rule, which interactive.html\'s sunLabelMarker calls -- must be an\n//   info cross whose words begin with the row\'s own name, the name the\n//   drawer shows. That test is worked out here from the traces\' words,\n//   not from the mark the rule reads. Rows that are not shells (the Moon,\n//   Earth\'s axis, the Sun direction, the terminator) are listed, not\n//   judged.\n//   It prints every row with the first line of the words it opens.\n//\n// WHAT MAKES IT FAIL\n//   A shell\'s row that opens another feature\'s words, or none, named by\n//   room and row. A SELF-TEST first plants the bug that was found: the\n//   streamer belt\'s traces built without the mark that says they were\n//   drawn with the corona, as before the fix; the corona\'s row must then\n//   be named.\n//\n// Module written: October 22, 2026 with Anthropic\'s Claude Opus 5.5 (new,\n// L-468).\n//\n// Role: devtool\n// Domain: dev_tools\n\n"use strict";\nconst fs = require("fs");\nconst path = require("path");\nconst ROOT = path.join(__dirname, "..");\nfunction read(rel) { return fs.readFileSync(path.join(ROOT, rel), "utf8"); }\n\nconst failures = [];\nfunction fail(m) { failures.push(m); }\n\nglobal.window = global;\neval(read("gallery/feature_renderers.js"));\neval(read("gallery/earth_geometry.js"));\nconst GF = global.GalleryFeatures;\nconst EG = global.EarthGeometry;\nconst coverage = JSON.parse(read("data/solar-system/coverage_index.json"));\nconst notes = GF.setFrameConstants(coverage.frame_constants);\nif (notes.length) fail("frame constants not served: " + notes.join("; "));\n(function () {\n  const dir = path.join(ROOT, "data", "solar-system", "drawings");\n  const map = {};\n  fs.readdirSync(dir).filter(n => /\\.json$/.test(n)).forEach(n => {\n    map[n.slice(0, -5)] = JSON.parse(fs.readFileSync(path.join(dir, n), "utf8"));\n  });\n  GF.setDrawings(map);\n})();\nconst config = JSON.parse(read("data/objects_config.json"));\nfunction featuresOf(slug) {\n  const o = (config.objects || []).find(x => x && x.slug === slug);\n  return Object.keys(o.features).map(k => ({ object: slug, feature: k, params: o.features[k] }));\n}\n\nfunction build() {\n  const sun = GF.buildFeatureTraces(featuresOf("sun"),\n    { sun: { name: "Sun", position: [0, 0, 0] } }, { sceneHalfRangeAu: 0.25 }).traces;\n  const p = JSON.parse(read("documentation/payload_earth_scene.json"));\n  p.features = featuresOf("earth");\n  const earth = EG.composeScene(p, { GF: GF, halfRangeAu: 6.155e-5,\n    epochIso: "x" }).traces;\n  return { sun: sun, earth: earth };\n}\n\nfunction plain(s) {\n  return String(s).replace(/<br[^>]*>/gi, " / ").replace(/<[^>]*>/g, "");\n}\n\n// The rows as the drawer builds them: by legend group, the shown name from\n// the trace that shows in the legend, the indices in trace order.\nfunction rowsOf(traces) {\n  const rows = [], byKey = {};\n  traces.forEach((t, i) => {\n    const g = t && t.legendgroup;\n    if (!g) return;\n    if (!byKey[g]) { byKey[g] = { key: g, name: t.name || g, indices: [], shell: false }; rows.push(byKey[g]); }\n    byKey[g].indices.push(i);\n    if (t.showlegend === true && t.name) byKey[g].name = t.name;\n    if (t.meta && typeof t.meta.shell_key === "string") byKey[g].shell = true;\n  });\n  return rows;\n}\n\nfunction judge(built) {\n  const bad = [], seen = [];\n  for (const room of ["sun", "earth"]) {\n    const traces = built[room];\n    for (const row of rowsOf(traces)) {\n      const i = GF.labelTraceIndex(traces, row.indices);\n      const words = i >= 0 ? plain(traces[i].text[0]) : null;\n      seen.push([room, row.name, row.shell, words]);\n      if (!row.shell) continue;\n      if (words === null) {\n        bad.push(room + ": the row " + JSON.stringify(row.name) + " opens no words");\n      } else if (words.indexOf(row.name) !== 0) {\n        bad.push(room + ": the row " + JSON.stringify(row.name) +\n                 " opens another feature\'s words: " + JSON.stringify(words.slice(0, 60)));\n      }\n    }\n  }\n  return { bad: bad, seen: seen };\n}\n\n// --- self-test: the bug that was found ---------------------------------\n(function selfTest() {\n  const real = build();\n  // Take the mark off every trace drawn with another, as before the fix.\n  for (const room of ["sun", "earth"]) {\n    real[room].forEach(t => {\n      if (t.meta && typeof t.meta.joined_to === "string") {\n        const m = Object.assign({}, t.meta); delete m.joined_to; t.meta = m;\n      }\n    });\n  }\n  const r = judge(real).bad.filter(b => /"Sun: Corona"/.test(b));\n  if (!r.length) fail("self-test: the streamer belt\'s cross unmarked, and the corona\'s row stayed green");\n  else console.log("  self-test: the streamer belt\'s cross unmarked -- red: " + r[0]);\n})();\n\n// --- the rooms -----------------------------------------------------------\nconst res = judge(build());\nres.bad.forEach(fail);\nlet shells = 0;\nres.seen.forEach(s => {\n  if (s[2]) shells += 1;\n  console.log("  " + s[0] + " / " + s[1] + (s[2] ? "" : " (not a shell, not judged)") +\n              ": " + (s[3] === null ? "(no words)" : s[3].slice(0, 70)));\n});\nconsole.log("");\nif (failures.length) {\n  console.log("=== LABEL WORDS: " + failures.length + " FAILURE(S)");\n  failures.forEach(f => console.log("  FAIL " + f));\n  process.exit(1);\n}\nconsole.log("=== LABEL WORDS: all " + shells + " shell rows in both rooms open " +\n            "their own feature\'s words; self-test red once");\n', 'documentation/fixture_hovers_L434_on_d7195704.json': '{\n "sun/Sun: Core": "Sun: Core<br><br>The Sun\'s center, where hydrogen fuses into helium and the Sun\'s light<br soft>and heat are made.<br><br>Radius: 0.25 solar radii<br>= 170,000 km (0.0012 AU)<br><br>For more information and references please click on the<br soft>info \\"i\\" button top right.",\n "sun/Sun: Radiative Zone": "Sun: Radiative Zone<br><br>The deep layer around the core where energy crawls outward as light,<br soft>absorbed and re-emitted countless times.<br><br>Radius: 0.71 solar radii<br>= 500,000 km (0.00332 AU)<br><br>For more information and references please click on the<br soft>info \\"i\\" button top right.",\n "sun/Sun: Photosphere": "Sun: Photosphere<br><br>The Sun\'s visible surface: the thin, glowing layer that the light we<br soft>see comes from.<br><br>Radius: 1 solar radius<br>= 695,700 km (0.00465 AU)<br><br>For more information and references please click on the<br soft>info \\"i\\" button top right.",\n "sun/Sun: Corona": "Sun: Streamer Belt (helmet and stalk)<br><br>The brightest part of the Sun\'s outer atmosphere, seen at a total<br soft>eclipse as the pearly white halo, shaped by the Sun\'s magnetic field.<br><br>Cusp: 4 solar radii<br>= 3,000,000 km (0.02 AU)<br>Helmets reach no higher than 2 to 4 solar radii; drawn at 4.<br>Fades to nothing by: 19.7 solar radii<br>= 13,700,000 km (0.092 AU)<br>Its warp and width are drawn to show the shape, not measured.<br><br>For more information and references please click on the<br soft>info \\"i\\" button top right.",\n "sun/Sun: Chromosphere (2,000 km skin)": "Sun: Chromosphere (2,000 km skin)<br><br>A thin, reddish layer of the Sun\'s atmosphere just above the visible<br soft>surface, about 2,000 km deep.<br><br>Radius: 1.003 solar radii<br>= 698,000 km (0.00466 AU)<br><br>For more information and references please click on the<br soft>info \\"i\\" button top right.",\n "sun/Sun: Roche Limit (Comets)": "Sun: Roche Limit (Comets)<br><br>The distance inside which the Sun\'s tides would pull a loosely held<br soft>comet apart.<br><br>Radius: 3 solar radii<br>= 2,000,000 km (0.02 AU)<br>Known only roughly, because comets differ in density. It is drawn<br soft>where the formula\'s middle answer falls; the true limit could lie a<br soft>little nearer the Sun or farther out.<br><br>For more information and references please click on the<br soft>info \\"i\\" button top right.",\n "sun/Sun: Alfven Surface": "Sun: Alfven Surface<br><br>The true outer edge of the Sun\'s atmosphere, where the outflowing gas<br soft>becomes the solar wind and can no longer signal back to the Sun.<br><br>Radius: 19.7 solar radii<br>= 13,700,000 km (0.092 AU)<br><br>For more information and references please click on the<br soft>info \\"i\\" button top right.",\n "sun/Sun: Corona#2": "Sun: Corona<br><br>The Sun\'s outer atmosphere, a very thin gas of electrons and ions. It<br soft>begins about 3,000 km above the visible surface, just above the<br soft>chromosphere, and has no outer edge. It thins out with height, and at<br soft>the Alfven surface, about 19.7 solar radii (13,700,000 km, 0.092 AU)<br soft>from the Sun\'s center, it becomes the solar wind.<br>Each dot\'s place shows how dense the gas is; its brightness shows how<br soft>much sunlight reaches it.<br>The streamer belt, drawn with it, is the part of the corona where the<br soft>Sun\'s magnetic field closes in loops.<br><br>For more information and references please click on the<br soft>info \\"i\\" button top right.",\n "sun/Sun: Zodiacal Dust Cloud (F-corona)": "Sun: Zodiacal Dust Cloud (F-corona)<br><br>Dust spread through the inner solar system, flattened toward the plane<br soft>the planets move in. It thins with distance from the Sun and has no<br soft>edge; the drawing stops at 5.2 AU (780,000,000 km).<br>Each dot\'s place shows how dense the dust is; its brightness shows how<br soft>much sunlight reaches it.<br>Near the Sun this dust is seen as the F-corona.<br><br>For more information and references please click on the<br soft>info \\"i\\" button top right.",\n "sun/Sun: Termination Shock": "Sun: Termination Shock<br><br>The place far beyond the planets where the solar wind slows suddenly<br soft>from supersonic speed as it meets the gas between the stars.<br><br>Radius: 94.01 AU<br>= 14,064,000,000 km<br><br>For more information and references please click on the<br soft>info \\"i\\" button top right.",\n "sun/Sun: Heliopause": "Sun: Heliopause<br><br>The outer boundary of the Sun\'s bubble, where the solar wind\'s push is<br soft>balanced by the gas between the stars.<br><br>Radius: 121 AU<br>= 18,100,000,000 km<br><br>For more information and references please click on the<br soft>info \\"i\\" button top right.",\n "sun/Sun: Hills Cloud (tilted disk)": "Sun: Hills Cloud (tilted disk)<br><br>The inner part of the Oort cloud: icy bodies far beyond the planets,<br soft>gathered in a slightly warped disk.<br><br>From 2,000 AU (300,000,000,000 km)<br soft>to 10,000 AU (1,000,000,000,000 km),<br soft>thinning out by 20,000 AU (3,000,000,000,000 km).<br>A 2025 computer model (Nesvorny and others) finds the disk tilted<br soft>about 30 degrees to the ecliptic, the plane of Earth\'s orbit, with two<br soft>spiral arms. The dots follow orbits like the model\'s; how stretched<br soft>the orbits are is chosen for the picture.<br><br>For more information and references please click on the<br soft>info \\"i\\" button top right.",\n "sun/Sun: Outer Oort Cloud (clumps)": "Sun: Outer Oort Cloud (clumps)<br><br>The outer Oort cloud: a rough sphere of icy bodies at the very edge of<br soft>the Sun\'s reach, drawn here as loose dots with clumps among them.<br><br>From 10,000 AU (1,000,000,000,000 km),<br soft>filling in by 20,000 AU (3,000,000,000,000 km),<br soft>to 100,000 AU (10,000,000,000,000 km)<br>It begins where the inner cloud\'s disk thins out.<br>Drawn as loose dots with clumps among them, to show the cloud is not<br soft>smooth; where the clumps really are is not known.<br><br>For more information and references please click on the<br soft>info \\"i\\" button top right.",\n "sun/Sun: Galactic Tide (sparse at the plane and poles)": "Sun: Galactic Tide (sparse at the plane and poles)<br><br>How the Milky Way\'s gravity sends comets in from the outer Oort cloud:<br soft>drawn thickest halfway between the galaxy\'s plane and its poles.<br><br>From 10,000 AU (1,000,000,000,000 km),<br soft>filling in by 20,000 AU (3,000,000,000,000 km),<br soft>to 100,000 AU (10,000,000,000,000 km)<br>Drawn tilted to the galaxy\'s plane; how thick it is at each latitude<br soft>follows how strongly the tide pulls there.<br>The pink cone marks where it is thickest, halfway between the plane<br soft>and the poles, where the tide changes comets\' orbits the most.<br>Where the comets really are is not known.<br><br>For more information and references please click on the<br soft>info \\"i\\" button top right.",\n "sun/Sun: Galactic Plane": "Sun: Galactic Plane<br><br>The plane of the Milky Way\'s disk, drawn as a ring around the Sun,<br soft>with a line along the galaxy\'s north-south axis, its two poles marked,<br soft>and the direction of the galaxy\'s centre.<br><br>For more information and references please click on the<br soft>info \\"i\\" button top right.",\n "sun/Sun: Galactic Plane#2": "North Galactic Pole (NGP)<br>Perpendicular to the disk of our galaxy<br><br>For more information and references please click on the<br soft>info \\"i\\" button top right.",\n "sun/Sun: Galactic Plane#3": "South Galactic Pole (SGP)<br>Perpendicular to the disk of our galaxy<br><br>For more information and references please click on the<br soft>info \\"i\\" button top right.",\n "sun/Sun: Galactic Plane#4": "Sagittarius A*<br>The direction of the centre of our galaxy, seen from the Sun<br><br>For more information and references please click on the<br soft>info \\"i\\" button top right.",\n "sun/Sun: Inner Limit of Oort Cloud": "Sun: Inner Limit of Oort Cloud<br><br>The inner edge of the Oort cloud, where the swarm of icy bodies is<br soft>thought to begin.<br><br>Radius: 2,000 AU<br>= 300,000,000,000 km<br>Thought to lie between 2,000 and 5,000 AU; drawn at 2,000.<br><br>For more information and references please click on the<br soft>info \\"i\\" button top right.",\n "sun/Sun: Inner Oort Cloud": "Sun: Inner Oort Cloud<br><br>The outer edge of the inner Oort cloud, where the flattened inner<br soft>swarm gives way to the spherical outer cloud.<br><br>Radius: 20,000 AU<br>= 3,000,000,000,000 km<br>The inner cloud gives way to the round outer cloud between 10,000 and<br soft>20,000 AU; this sphere is drawn at 20,000 AU, the far end.<br><br>For more information and references please click on the<br soft>info \\"i\\" button top right.",\n "sun/Sun: Outer Oort Cloud": "Sun: Outer Oort Cloud<br><br>The outer edge of the Oort cloud, about two light-years from the Sun,<br soft>where the Sun\'s realm gives way to the space between the stars.<br><br>Radius: 100,000 AU<br>= 10,000,000,000,000 km<br>Thought to lie between 10,000 and 100,000 AU; drawn at 100,000.<br><br>For more information and references please click on the<br soft>info \\"i\\" button top right.",\n "sun/Sun: Gravitational Influence": "Sun: Gravitational Influence<br><br>The outer limit of the Sun\'s gravitational hold: how far out a body<br soft>can still belong to the Sun rather than to the galaxy.<br><br>Radius: 134,000 AU<br>= 20,100,000,000,000 km<br>The Sun\'s Hill radius in the galaxy, calculated where the galaxy\'s<br soft>tidal pull overtakes the Sun\'s gravity: about 0.65 parsecs.<br soft>Calculated, not measured.<br><br>For more information and references please click on the<br soft>info \\"i\\" button top right.",\n "jupiter/Jupiter: Main Ring": "Jupiter: Main Ring<br><br>Inner edge: 122,500 km (0.000819 AU)<br>Outer edge: 129,000 km (0.000862 AU)<br>Thickness: 30 km (2.01e-7 AU)<br>Drawn from the served cache; radii as measured.<br><br>For more information and references please click on the<br soft>info \\"i\\" button top right.",\n "jupiter/Jupiter: Halo Ring": "Jupiter: Halo Ring<br><br>Inner edge: 100,000 km (0.000668 AU)<br>Outer edge: 122,500 km (0.000819 AU)<br>Thickness: 12,500 km (0.0000836 AU)<br>Drawn from the served cache; radii as measured.<br><br>For more information and references please click on the<br soft>info \\"i\\" button top right.",\n "jupiter/Jupiter: Amalthea Gossamer Ring": "Jupiter: Amalthea Gossamer Ring<br><br>Inner edge: 129,000 km (0.000862 AU)<br>Outer edge: 182,000 km (0.00122 AU)<br>Thickness: 2,000 km (0.0000134 AU)<br>Drawn from the served cache; radii as measured.<br><br>For more information and references please click on the<br soft>info \\"i\\" button top right.",\n "jupiter/Jupiter: Thebe Gossamer Ring": "Jupiter: Thebe Gossamer Ring<br><br>Inner edge: 129,000 km (0.000862 AU)<br>Outer edge: 226,000 km (0.00151 AU)<br>Thickness: 8,600 km (0.0000575 AU)<br>Drawn from the served cache; radii as measured.<br><br>For more information and references please click on the<br soft>info \\"i\\" button top right.",\n "jupiter/Jupiter: Inner Radiation Belt": "Jupiter: Inner Radiation Belt<br><br>Drawn at 1.5 Jupiter radii<br>= 107,238 km (0.000717 AU)<br>Drawn 0.5 radii wide, a width chosen for the picture.<br>The ring lies in Jupiter\'s equatorial plane, the daily average of the<br soft>magnetic equator, which is tilted from it and turns with Jupiter<br soft>once a day.<br><br>For more information and references please click on the<br soft>info \\"i\\" button top right.",\n "jupiter/Jupiter: Middle Radiation Belt": "Jupiter: Middle Radiation Belt<br><br>Drawn at 3.0 Jupiter radii<br>= 214,476 km (0.00143 AU)<br>Drawn 0.5 radii wide, a width chosen for the picture.<br>The ring lies in Jupiter\'s equatorial plane, the daily average of the<br soft>magnetic equator, which is tilted from it and turns with Jupiter<br soft>once a day.<br><br>For more information and references please click on the<br soft>info \\"i\\" button top right.",\n "jupiter/Jupiter: Outer Radiation Belt": "Jupiter: Outer Radiation Belt<br><br>Drawn at 6.0 Jupiter radii<br>= 428,952 km (0.00287 AU)<br>Drawn 0.5 radii wide, a width chosen for the picture.<br>The ring lies in Jupiter\'s equatorial plane, the daily average of the<br soft>magnetic equator, which is tilted from it and turns with Jupiter<br soft>once a day.<br><br>For more information and references please click on the<br soft>info \\"i\\" button top right.",\n "saturn/Saturn: D Ring": "Saturn: D Ring<br><br>Inner edge: 66,900 km (0.000447 AU)<br>Outer edge: 74,500 km (0.000498 AU)<br>Drawn from the served cache; radii as measured.<br><br>For more information and references please click on the<br soft>info \\"i\\" button top right.",\n "saturn/Saturn: C Ring": "Saturn: C Ring<br><br>Inner edge: 74,658 km (0.000499 AU)<br>Outer edge: 92,000 km (0.000615 AU)<br>Drawn from the served cache; radii as measured.<br><br>For more information and references please click on the<br soft>info \\"i\\" button top right.",\n "saturn/Saturn: B Ring": "Saturn: B Ring<br><br>Inner edge: 92,000 km (0.000615 AU)<br>Outer edge: 117,500 km (0.000785 AU)<br>Drawn from the served cache; radii as measured.<br><br>For more information and references please click on the<br soft>info \\"i\\" button top right.",\n "saturn/Saturn: A Ring": "Saturn: A Ring<br><br>Inner edge: 122,340 km (0.000818 AU)<br>Outer edge: 136,800 km (0.000914 AU)<br>Drawn from the served cache; radii as measured.<br><br>For more information and references please click on the<br soft>info \\"i\\" button top right.",\n "saturn/Saturn: F Ring": "Saturn: F Ring<br><br>Inner edge: 140,210 km (0.000937 AU)<br>Outer edge: 140,420 km (0.000939 AU)<br>Drawn from the served cache; radii as measured.<br><br>For more information and references please click on the<br soft>info \\"i\\" button top right.",\n "saturn/Saturn: G Ring": "Saturn: G Ring<br><br>Inner edge: 166,000 km (0.00111 AU)<br>Outer edge: 175,000 km (0.00117 AU)<br>Drawn from the served cache; radii as measured.<br><br>For more information and references please click on the<br soft>info \\"i\\" button top right.",\n "saturn/Saturn: E Ring": "Saturn: E Ring<br><br>Inner edge: 180,000 km (0.00120 AU)<br>Outer edge: 480,000 km (0.00321 AU)<br>Drawn from the served cache; radii as measured.<br><br>For more information and references please click on the<br soft>info \\"i\\" button top right.",\n "earth/Earth: Magnetopause": "Earth: Magnetopause<br><br>The outer boundary of Earth\'s magnetic field, where it holds off the<br soft>solar wind: pressed in by day, trailing a long tail by night.<br><br>Sunward standoff: 10.3 Earth radii<br>That is about 65,000 km (0.00044 AU). Spacecraft that cross the real<br soft>boundary typically find it within 1.23 Earth radii of this model.<br>Drawn to 120 deg from the nose, as far as the paper plots its model.<br soft>Beyond that angle the boundary is drawn as the magnetotail.<br>Not tilted: the model is symmetric about the Sun line.<br>It is drawn along the line from the Sun to Earth; the real boundary\'s<br soft>nose is turned a few degrees toward the direction Earth moves in its<br soft>orbit, by an amount that depends on the solar wind\'s speed.<br><br>For more information and references please click on the<br soft>info \\"i\\" button top right.",\n "earth/Earth: Magnetotail": "Earth: Magnetotail<br><br>Earth\'s magnetic field, drawn out by the solar wind into a long tail<br soft>on the night side.<br><br>Spacecraft found the tail stops widening about 120 Earth radii behind<br soft>Earth, plus or minus 10, and is about 60 Earth radii wide beyond<br soft>there, plus or minus 5.<br>That is about 800,000 km (0.005 AU) and 400,000 km (0.003 AU).<br>The straight widening up to that point is our choice; the measurements<br soft>give only its two ends.<br>The drawing stops at 220 Earth radii, which is how far the spacecraft<br soft>went, not where the tail ends.<br>Drawn round, its average shape; at any moment it is often flattened.<br><br>For more information and references please click on the<br soft>info \\"i\\" button top right.",\n "earth/Earth: Bow Shock": "Earth: Bow Shock<br><br>The shock wave where the supersonic solar wind first slows as it hits<br soft>Earth\'s magnetic field, like the bow wave of a boat.<br><br>Sunward standoff: 13.5 Earth radii<br>That is about 86,000 km (0.00058 AU). Spacecraft that cross the real<br soft>shock typically find it within 0.69 Earth radii of this model.<br>Drawn to 105 deg from the nose, which is how far round the crossings<br soft>the fit was made from actually reached.<br>Not tilted: the fit is symmetric about the Sun line.<br>It is drawn along the line from the Sun to Earth; the real shock\'s<br soft>nose is turned a few degrees toward the direction Earth moves in its<br soft>orbit, by an amount that depends on the solar wind\'s speed.<br><br>For more information and references please click on the<br soft>info \\"i\\" button top right.",\n "earth/Earth: Inner Radiation Belt": "Earth: Inner Radiation Belt<br><br>A belt of trapped charged particles, mostly protons, held by Earth\'s<br soft>magnetic field close above the atmosphere.<br><br>The belt is one continuous region. Its dots follow Earth\'s magnetic<br soft>field lines, which curve from the equator down toward the ground, and<br soft>they are thickest where the belt is most intense. How they thin out is<br soft>drawn to show the shape, not measured.<br>Thickest at 1.5 Earth radii from Earth\'s centre, at the magnetic<br soft>equator: near where the measured flux of trapped protons is greatest.<br>= 9,600 km (0.00006 AU)<br>Measured extent: 1.1 to 2 Earth radii<br><br>For more information and references please click on the<br soft>info \\"i\\" button top right.",\n "earth/Earth: Outer Radiation Belt": "Earth: Outer Radiation Belt<br><br>A broader belt of trapped electrons farther out, that swells and<br soft>shrinks with solar storms.<br><br>The belt is one continuous region. Its dots follow Earth\'s magnetic<br soft>field lines, which curve from the equator down toward the ground, and<br soft>they are thickest where the belt is most intense. How they thin out is<br soft>drawn to show the shape, not measured.<br>Thickest at 4.5 Earth radii: halfway across the band, 4 to 5 Earth<br soft>radii out at the magnetic equator, where the belt is most intense. The<br soft>halfway point is our choice for the picture, not a measured peak.<br>Measured extent: 3 to 7 Earth radii<br><br>For more information and references please click on the<br soft>info \\"i\\" button top right.",\n "scene/moon": "Moon (osculating orbit)<br>r = 0.002383 AU (3.566e+05 km)<br>x = -0.000596 AU, y = 0.002303 AU, z = 0.000145 AU",\n "scene/moon#2": "Moon<br>r = 0.002705 AU (4.046e+05 km)<br>x = 0.000238 AU, y = -0.002688 AU, z = -0.000191 AU",\n "scene/moon#3": "Moon",\n "scene/Earth: Rotation Axis and Equator": "<b>Earth: Rotation Axis and Equator</b><br><br>North pole up the gold line; the ring is the equator on the crust.<br>Tilt: [the served tilt of date, graded above], measured against the orbit of the<br soft>Earth-Moon barycenter, the gravitational center of the Earth-Moon<br soft>system, around the Sun that day (JPL Horizons).<br>The axis slowly circles over thousands of years and nods slightly, so<br soft>the pole and the tilt belong to that date.<br>Axis drawn to 7,827 km (0.0000523 AU) -- a drawing length.<br>The curved arrows at both ends show the sense of the turning:<br soft>prograde, west to east, counter-clockwise seen from above the north<br soft>pole. Earth turns once every 23.93447 hours measured against the<br soft>stars. The turning is not animated, because nothing on the crust marks<br soft>a longitude to watch it by.<br><br>For more information and references please click on the<br soft>info \\"i\\" button top right.",\n "scene/Earth: Sun Direction": "<b>Earth: Sun Direction</b><br><br>Toward the Sun at 2026-09-09, from Earth\'s centre.<br>The dot where the line leaves the crust is the subsolar point, where<br soft>the Sun is overhead.<br>Earth-Sun distance: 149,117,173 km (0.997 AU)<br>Line drawn to the edge of the arrival frame; the Sun is far beyond it.<br><br>For more information and references please click on the<br soft>info \\"i\\" button top right.",\n "scene/Earth: Terminator (day-night line)": "<b>Earth: Terminator (day-night line)</b><br><br>The white circle is where the Sun is on the horizon: the sunlit half<br soft>of Earth faces the Sun line, the night half faces away. The yellow<br soft>line through the circle\'s centre is the Sun direction; its dot on the<br soft>crust is the subsolar point, where the Sun is overhead.<br><br>FROZEN at 2026-09-09. The real terminator sweeps around Earth once a<br soft>day; this scene does not turn. Geometry only -- no lighting is<br soft>modelled, and the refraction and solar-disc corrections that define<br soft>sunrise on the ground are not applied.<br><br><br><br>For more information and references please click on the<br soft>info \\"i\\" button top right.",\n "scene/moon#4": "<b>Moon: trusted arc of the orbit</b><br><br>The brighter arc is the part of the Moon\'s orbit where this page\'s<br soft>propagation is trusted to within 0.5 deg: 3.36 days either side of the<br soft>elements\' epoch.<br>The arc runs from 2026-10-13 15:00 to 2026-10-20 08:00 (UTC).<br>There is no longer span to choose: this scene is one epoch, and the<br soft>arc is the stretch of orbit the served elements are trusted for.<br>The faint full ellipse is the same orbit swept once around; outside<br soft>the arc, the Moon\'s real path drifts from it as the Sun and Earth\'s<br soft>shape perturb the two-body orbit.<br><br><br><br>For more information and references please click on the<br soft>info \\"i\\" button top right."\n}\n'}

import hashlib
import os
import sys


def main():
    texts, crlf = {}, {}
    for path, want in FINGERPRINTS.items():
        try:
            with open(path, 'rb') as f:
                raw = f.read()
        except OSError as e:
            print('ERROR: cannot read %s (%s). Run from the folder this patch '
                  'names. NOTHING was written.' % (path, e))
            return 1
        crlf[path] = b'\r\n' in raw
        text = raw.replace(b'\r\n', b'\n').decode('utf-8')
        got = hashlib.md5(text.encode('utf-8')).hexdigest()
        if got != want:
            print('ERROR: %s is not the file this patch was built on '
                  '(fingerprint %s, expected %s). NOTHING was written.'
                  % (path, got, want))
            return 1
        texts[path] = text
    for path in NEW_FILES:
        if os.path.exists(path):
            print('ERROR: %s already exists; this patch creates it. NOTHING '
                  'was written.' % path)
            return 1
    out = {}
    for path, pairs in EDITS.items():
        t = texts[path]
        for i, (old, new) in enumerate(pairs):
            n = t.count(old)
            if n != 1:
                print('ANCHOR FAIL: %s edit %d matched %d times. NOTHING was '
                      'written.' % (path, i + 1, n))
                return 1
            t = t.replace(old, new)
        before = set(texts[path].split('\n'))
        bad = [x for x in t.split('\n')
               if x not in before and any(ord(c) > 127 for c in x)]
        if bad:
            print('ERROR: a line this patch inserts in %s is not ASCII. '
                  'NOTHING was written.' % path)
            return 1
        out[path] = t
    for path, t in NEW_FILES.items():
        if any(ord(c) > 127 for c in t):
            print('ERROR: %s is not ASCII. NOTHING was written.' % path)
            return 1
    for path, t in out.items():
        with open(path, 'wb') as f:
            f.write(t.encode('utf-8'))
        print('ok  %s: %d edit(s)' % (path, len(EDITS[path])))
        if crlf[path]:
            print('note: %s was CRLF in the working copy; written LF' % path)
    for path, t in NEW_FILES.items():
        folder = os.path.dirname(path)
        if folder:
            os.makedirs(folder, exist_ok=True)
        with open(path, 'wb') as f:
            f.write(t.encode('utf-8'))
        print('ok  %s: created' % path)
    for path in STAMPS:
        print('stamped (its own Module updated line): %s' % path)
    print(AFTER)
    print('patch applied')
    return 0


if __name__ == '__main__':
    sys.exit(main())
